-- First batch of German article translations (Task "multilingual
-- articles", phase 1): proves the translations.body_html pipeline
-- end-to-end before translating the remaining ~39 English articles and
-- extending to Spanish/Italian/Russian/Japanese/Chinese.
--
-- Deliberately started with the 5 shortest English articles (~2,000-4,200
-- characters each) rather than the longest ones, to validate the full
-- chain -- admin-authored EN body -> human/AI German translation ->
-- translations row -> getTranslatedArticleBySlug() ->
-- /de/maldives/travel-guide/[article] rendering -- on real content before
-- committing to translating the 10,000+ word articles.
--
-- Every row keeps the real English entity_id (the canonical article never
-- moves or duplicates) and gets its own German slug, title and body --
-- internal links inside the body intentionally still point at the English
-- URLs (e.g. /maldives/islands/male/), since those verticals don't have a
-- translated route yet; this matches the same "stays English until that
-- area is translated too" convention already used on the /de/maldives hub
-- page for its "Explore More" links.
-- FIX (applied after discovering the bug): entity_id below is resolved via a
-- scalar subquery on the canonical English article slug, NOT a hardcoded
-- UUID literal. nodes.id is generated by gen_random_uuid() at insert time with
-- no explicit id column in the seeding migration, so the same article gets a
-- different random UUID in every database (local sandbox vs. production). A
-- literal UUID captured from one database's nodes table will never match row
-- in another, causing translations_entity_id_fkey violations. Resolving by
-- slug instead makes this migration portable across any database that has
-- run the legacy_articles seed migration.
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'male-airport-velana-international-airport'), 'article', 'de', 'male-flughafen-velana-international-airport', 'Malé Flughafen | Velana International Airport', 'Erfahren Sie alles Wissenswerte über den Malé Flughafen, auch bekannt als Velana International Airport, das wichtigste Tor zu den Malediven. Informationen zu Flügen, Einrichtungen und mehr.', null, '<h2>Einführung</h2><p>Der Velana International Airport, weithin bekannt als <a href="/maldives/islands/male/">Malé</a> Flughafen, ist das wichtigste internationale Tor zu den atemberaubenden Inseln der Malediven. Er liegt auf der Insel Hulhulé, nur eine kurze Strecke von der Hauptstadt Malé entfernt, und ist ein zentraler Knotenpunkt für Reisende aus aller Welt. Mit modernsten Einrichtungen, umfangreichen Flugverbindungen und erstklassigem Service spielt der Malé Flughafen eine entscheidende Rolle für den maledivischen Tourismus und fertigt jährlich Millionen von Passagieren ab.</p><p>Die Malediven sind berühmt für ihre idyllischen Strände, kristallklares Wasser und luxuriöse Resorts. Ob Familienurlaub, romantische Flitterwochen oder abenteuerliche Solo-Reise – Ihre Reise beginnt am Velana International Airport. Dieser Ratgeber gibt Ihnen einen ausführlichen Überblick über alles Wichtige rund um den Malé Flughafen: seine Geschichte, seine Einrichtungen, die Transportmöglichkeiten und praktische Reisetipps.</p><h4>Schnellnavigation</h4><p>Flughafenübersicht Fluginformationen Einrichtungen und Service Transport und Erreichbarkeit Reisetipps für den Velana International Airport Karte des Flughafens Aktivitäten am Flughafen der Malediven Liste der Flughäfen der Malediven Häufig gestellte Fragen</p><h2>Flughafenübersicht</h2><p>Der Velana International Airport (IATA: MLE, ICAO: VRMM) ist der verkehrsreichste und bedeutendste Flughafen der Malediven und dient sowohl internationalen Touristen als auch einheimischen Reisenden als wichtigster Eingangspunkt. Seine strategische Lage auf der Insel Hulhulé, direkt neben der Hauptstadt Malé, macht ihn zu einem unverzichtbaren Drehkreuz für den Luftverkehr in der Region.</p><p>Ursprünglich als Hulhulé Airport bekannt, wurde er 1960 eröffnet und seitdem mehrfach erweitert und modernisiert, um der wachsenden Zahl von Besuchern der Malediven gerecht zu werden. Im Jahr 2017 wurde der Flughafen zu Ehren von Ibrahim Nasir, dem zweiten Präsidenten der Malediven, der eine bedeutende Rolle bei der Entwicklung des Landes spielte, in Velana International Airport umbenannt. Heute verfügt der Velana International Airport über moderne Einrichtungen, darunter eine neue Start- und Landebahn, die selbst die größten Flugzeuge der Welt wie den Airbus A380 abfertigen kann.</p>', 'Malé Flughafen | Velana International Airport | Malediven Reiseführer | MTG', 'Erfahren Sie alles Wissenswerte über den Malé Flughafen, auch bekannt als Velana International Airport, das wichtigste Tor zu den Malediven. Informationen zu Flügen, Einrichtungen und mehr.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'gaafu-atoll-fishing-guide-mfh-maamendhoo'), 'article', 'de', 'angeln-gaafu-atoll-leitfaden-lodge-charter-maamendhoo', 'Angeln im Gaafu-Atoll: Ein Leitfaden zu unserer Lodge und unserem Charter auf Maamendhoo', 'Das Charterboot, die Preise und die Mehrtagespakete, die wir von unserer eigenen Lodge auf Maamendhoo im Gaafu-Alifu-Atoll aus anbieten.', null, '<p>Maamendhoo, eine Insel im Gaafu-Alifu-Atoll im Süden der Malediven, ist die Heimat unserer eigenen Lodge und des dazugehörigen Charterbetriebs. Dieser Leitfaden behandelt das Boot, die Charterpreise und die darauf aufgebauten Mehrtagespakete.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge.jpeg" alt="Maldives Fishing and Holidays Lodge, Maamendhoo, Gaafu-Alifu-Atoll" loading="lazy" /></figure><h2>Die Lodge</h2><p><a href="/maldives/guesthouses/maldives-fishing-and-holidays-lodge/">Unsere Lodge</a> ist eine Pension auf Maamendhoo mit Vollpension-Zimmern für bis zu 2 Gäste pro Zimmer, betrieben vom selben Anbieter wie die Angelcharter – Unterkunft und Angeltouren werden also aus einer Hand gebucht, statt getrennt organisiert werden zu müssen.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge-hotel.jpeg" alt="Maldives Fishing and Holidays Lodge" loading="lazy" /></figure><h2>Das Boot</h2><p>Die Charter finden an Bord der „Emperor" statt, einem 32-Fuß-Angelboot mit zwei 200-PS-Außenbordmotoren und einer maximalen Kapazität von 5 Passagieren.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-charter-boat.webp" alt="Charterboot zum Angeln auf den Malediven" loading="lazy" /></figure><h2>Preise für private Charter</h2><p>Zwei private Charter sind direkt buchbar, mit Preisen pro Boot statt pro Person:</p><ul><li><a href="/maldives/fishing/private-full-day-fishing-charter/">Privater Ganztages-Angelcharter</a> – ab 1.380 USD pro Boot, etwa 8 Stunden.</li><li><a href="/maldives/fishing/private-half-day-fishing-charter/">Privater Halbtages-Angelcharter</a> – ab 980 USD pro Boot, etwa 4 Stunden.</li></ul><h2>Mehrtägige Angelpakete</h2><p>Über die beiden Einzelcharter hinaus bietet der Betreiber 14 Mehrtagespakete von 2 bis 8 Nächten an, jeweils als Ganztages- oder Halbtages-Angelvariante erhältlich. Sie beinhalten den Lodge-Aufenthalt, einen Inlandsflug hin und zurück, den Bootstransfer sowie die entsprechende Anzahl an Chartertagen. Die Preise sind nach Gruppengröße von 1 bis 5 Gästen pro Boot gestaffelt, wobei 5 Gäste den besten Preis pro Person erhalten. Das <a href="/maldives/packages/2-night-maldives-fishing-package-full-day-fishing/">2-Nächte-Paket</a> und das <a href="/maldives/packages/8-night-maldives-fishing-package-full-day-fishing/">8-Nächte-Paket</a> markieren die beiden Enden dieser Spanne – die vollständige <a href="/maldives/packages/fishing/">Übersicht der Angelpakete</a> zeigt alle verfügbaren Dauern.</p><h2>Anreise</h2><p>Die Pakete rund um Maamendhoo kombinieren einen Inlandsflug hin und zurück mit einem Bootstransfer zur Insel – beides wird als Teil des Pakets organisiert und muss nicht separat gebucht werden.</p><h2>Buchung</h2><p>Alle oben genannten Angebote sind Anfrage-basierte Buchungen – kontaktieren Sie uns über die <a href="/maldives/providers/maldives-fishing-and-holiday/">Anbieterseite</a>, oder starten Sie direkt von der jeweiligen Charter- oder Paketseite, die zu Ihrer Reise passt.</p>', 'Angeln im Gaafu-Atoll: Ein Leitfaden zu unserer Lodge und unserem Charter auf Maamendhoo | Malediven Reiseführer | MTG', 'Das Charterboot, die Preise und die Mehrtagespakete, die wir von unserer eigenen Lodge auf Maamendhoo im Gaafu-Alifu-Atoll aus anbieten.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-techniques-guide'), 'article', 'de', 'malediven-angeltechniken-schleppfischen-jiggen-poppen-handleinenfischen', 'Angeltechniken auf den Malediven: Schleppfischen, Jiggen, Poppen und Handleinenfischen erklärt', 'Ein verständlicher Leitfaden zu den wichtigsten Angeltechniken rund um die maledivischen Atolle – Schleppfischen, Jiggen, Poppen und Handleinenfischen – und welche Arten mit welcher Technik gefangen werden.', null, '<p>Die meisten in den Malediven gebuchten Angeltouren lassen sich einer von wenigen Techniken zuordnen, die jeweils für unterschiedliche Fischarten und Gewässerabschnitte geeignet sind. Dieser Leitfaden erklärt, was jede Technik beinhaltet und welche Fische Sie damit wahrscheinlich fangen werden.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/maldives-atoll-aerial-view.webp" alt="Luftaufnahme eines maledivischen Atolls" loading="lazy" /></figure><h2>Schleppfischen (Trolling)</h2><p>Beim Schleppfischen werden Leinen mit Ködern oder Fischfetzen hinter einem fahrenden Boot gezogen, meist entlang der Atollränder oder an Riffabbrüchen, wo pelagische Fische vorbeiziehen. Es ist die Standardtechnik für Wahoo – einer der schnellsten Fische im Ozean mit Geschwindigkeiten von bis zu 80 km/h – und wird auch für Gelbflossenthun und Goldmakrele eingesetzt, die sich häufig in der Nähe von treibendem Geäst aufhalten.</p><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Wahoo auf den Malediven" loading="lazy" /></figure><h2>Jiggen</h2><p>Beim Jiggen wird ein beschwerter Metallköder senkrecht in Bodennähe geführt, über tiefen Riffhängen und -abbrüchen statt im offenen Wasser des Schleppfischens. Diese Methode wird am häufigsten mit dem Doggezahnthun in Verbindung gebracht, einem einzelgängerischen, kampfstarken Raubfisch, der genau in solchen Strukturen lebt.</p><figure><img src="legacy/fishing/images/dogtooth-tuna-in-maldives.webp" alt="Doggezahnthun auf den Malediven" loading="lazy" /></figure><h2>Poppen</h2><p>Beim Poppen wird ein Oberflächenköder in Richtung Riffkanten und Kanäle geworfen und in kurzen, spritzenden Stößen eingeholt, um einen Biss an der Oberfläche statt in der Tiefe zu provozieren. Diese Technik ist am engsten mit dem Trevally verbunden, für den die Malediven international zu den besten Zielgebieten zählen.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/giant-trevally.webp" alt="Beim Angeln auf den Malediven gefangener Trevally" loading="lazy" /></figure><h2>Handleinen- und Grundfischen</h2><p>Das Handleinenfischen – Rolle, Leine, Haken und Köder, von Hand geführt statt geworfen und eingeholt – ist die traditionelle Technik mit der niedrigsten Einstiegshürde. Sie wird häufig als einführender Sonnenuntergangs-Ausflug angeboten und erfordert keine Vorerfahrung. Sie bildet zudem die Grundlage der traditionellen Pole-and-Line-Fischerei auf Echten Bonito in den Malediven. Das Grundfischen, eine eng verwandte Technik, bei der vor Anker über Riffstrukturen gefischt wird, ist die übliche Methode, um Zackenbarsche und Schnapper zu fangen.</p><figure><img src="legacy/images/fishing/tuna-fish-in-maldives.webp" alt="Echter Bonito auf den Malediven" loading="lazy" /></figure><figure><img src="uploads/assets/uploads/fishing/images/gallery/reef-fishing-grouper.webp" alt="Zackenbarsch beim Riffangeln auf den Malediven" loading="lazy" /></figure><h2>Die richtige Technik wählen</h2><p>Wenn Sie einen einfachen, geselligen ersten Ausflug möchten, benötigt eine Handleinen- oder Sonnenuntergangstour keinerlei Erfahrung. Wenn Sie eine bestimmte Trophäenart im Visier haben, richtet sich die Technik nach dem Fisch: Schleppfischen für Wahoo und Thunfisch, Jiggen für Doggezahnthun, Poppen für Trevally. Unsere eigenen <a href="/maldives/providers/maldives-fishing-and-holiday/">privaten Charter</a> ab Maamendhoo decken Schleppfischen und Grundfischen an Bord der „Emperor" ab – siehe unsere Seite zum <a href="/maldives/fishing/private-full-day-fishing-charter/">Ganztagescharter</a>, oder durchstöbern Sie den vollständigen <a href="/maldives/fishing/#fish-species">Fischarten-Leitfaden</a> für mehr Informationen darüber, was Sie fangen könnten.</p>', 'Angeltechniken auf den Malediven: Schleppfischen, Jiggen, Poppen und Handleinenfischen erklärt | Malediven Reiseführer | MTG', 'Ein verständlicher Leitfaden zu den wichtigsten Angeltechniken rund um die maledivischen Atolle – Schleppfischen, Jiggen, Poppen und Handleinenfischen – und welche Arten mit welcher Technik gefangen werden.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-seasons-month-by-month-guide'), 'article', 'de', 'malediven-angelsaisons-monat-fuer-monat-leitfaden', 'Angelsaisons auf den Malediven: Ein Monat-für-Monat-Leitfaden', 'Wann Sie welche Fischart rund um die maledivischen Atolle am besten angeln können – vom Thunfisch- und Wahoo-Lauf während des Nordost-Monsuns bis zur anschließenden Trevally-Saison.', null, '<p>Die Angelbedingungen rund um die Malediven ändern sich mit den beiden Monsunzeiten des Landes, und mehrere der Fischarten, für die Angler hierher reisen, haben innerhalb dieses Musters ihre eigene Saison. Dieser Leitfaden zeigt, was zu welcher Zeit realistisch am ergiebigsten ist, basierend auf denselben Artendaten, die in unserem gesamten <a href="/maldives/fishing/">Malediven-Angelführer</a> verwendet werden.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-liveaboard-maldives.webp" alt="Angel-Liveaboard auf den Malediven" loading="lazy" /></figure><h2>Die beiden Monsune</h2><p>Die Malediven liegen in einem tropischen Monsunklima mit zwei großen Jahreszeiten. Der Nordost-Monsun, lokal Iruvai genannt, dauert etwa von Dezember bis April und bringt ruhigere See und weniger Regen – das verlässlichere Zeitfenster für Bootsausflüge jeder Art. Der Südwest-Monsun, Hulhangu, dauert etwa von Mai bis November, mit mehr Regen und raueren Gewässern an den meisten Tagen, obwohl Touren während dieser Zeit weiterhin stattfinden und einige der besten Sportfischarten in dieser Periode aktiver sind.</p><h2>Beste Saison nach Fischart</h2><p>Das sind die saisonalen Muster hinter den Arten aus unserem <a href="/maldives/fishing/#fish-species">Fischarten-Leitfaden</a>:</p><ul><li><strong>Gelbflossenthun</strong> – Dezember bis März, während des ruhigeren Nordost-Monsuns.</li><li><strong>Wahoo</strong> – Dezember bis März, im selben Zeitfenster, meist beim Schleppfischen gefangen.</li><li><strong>Goldmakrele (Mahi-Mahi)</strong> – Dezember bis April, häufig in der Nähe von treibendem Geäst und FADs (fischsammelnden Vorrichtungen).</li><li><strong>Doggezahnthun</strong> – November bis April, an den tieferen Riffhängen und -abbrüchen.</li><li><strong>Trevally</strong> – April bis Oktober, über den Übergang zum Südwest-Monsun hinweg.</li><li><strong>Echter Bonito</strong> – ganzjährig, das Rückgrat der traditionellen Pole-and-Line-Fischerei der Malediven.</li></ul><h2>Dezember bis April: der Nordost-Monsun-Lauf</h2><p>Dies ist das Zeitfenster, in dem Gelbflossenthun, Wahoo und Goldmakrele gleichzeitig Saison haben, und ruhigere See sorgt für angenehmere Tage auf dem Wasser und bessere Bedingungen beim Schleppfischen entlang der Atollränder.</p><figure><img src="legacy/fishing/images/yellowfin-tuna.webp" alt="Gelbflossenthun auf den Malediven" loading="lazy" /></figure><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Wahoo auf den Malediven" loading="lazy" /></figure><h2>April bis Oktober: Trevally-Saison</h2><p>Mit dem Übergang zum Südwest-Monsun beginnt die Saison für den Trevally. GTs gelten als das Aushängeschild des Sportfischens auf den Malediven, patrouillieren entlang Riffkanten und Kanälen und sind für ihre explosiven Bisse bekannt – das Land zählt weltweit zu den besten Zielgebieten für trophäengroße Trevallys.</p><figure><img src="legacy/images/fishing/giant-trevally-fish.webp" alt="Trevally auf den Malediven" loading="lazy" /></figure><h2>Buchung passend zur Saison</h2><p>Unser eigener <a href="/maldives/providers/maldives-fishing-and-holiday/">Charterbetrieb</a> bietet ganzjährig private Charter ab Maamendhoo im Gaafu-Alifu-Atoll an Bord des Boots „Emperor" an – siehe unsere Seiten zum <a href="/maldives/fishing/private-full-day-fishing-charter/">Ganztages-</a> und <a href="/maldives/fishing/private-half-day-fishing-charter/">Halbtagescharter</a> für aktuelle Preise, oder lesen Sie den vollständigen Bericht in unserem <a href="/maldives/travel-guide/gaafu-atoll-fishing-guide-mfh-maamendhoo/">Gaafu-Atoll-Angelführer</a>.</p>', 'Angelsaisons auf den Malediven: Ein Monat-für-Monat-Leitfaden | Malediven Reiseführer | MTG', 'Wann Sie welche Fischart rund um die maledivischen Atolle am besten angeln können – vom Thunfisch- und Wahoo-Lauf während des Nordost-Monsuns bis zur anschließenden Trevally-Saison.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'where-is-maldives-located'), 'article', 'de', 'wo-liegen-die-malediven', 'Wo liegen die Malediven?', 'Wo liegen die Malediven? Entdecken Sie, wo sich dieses tropische Paradies befindet und warum es für Reisende aus aller Welt zu den Top-Reisezielen zählt.', null, '<h2>Ein Überblick über die Lage der Malediven</h2><p>Die Malediven, offiziell die Republik Malediven, sind ein tropisches Paradies im Indischen Ozean. Südwestlich von Sri Lanka und Indien gelegen, bestehen die Malediven aus einer Kette von 26 Atollen, die sich aus über 1.000 Koralleninseln zusammensetzen. Dieses wunderschöne Land ist berühmt für seine traumhaften weißen Sandstrände, kristallklares türkisfarbenes Wasser und lebendige Korallenriffe – ein begehrtes Ziel für Reisende, die Ruhe und Naturschönheit suchen.</p><h2>Karte der Malediven</h2><h2>Geografische Koordinaten</h2><figure><img src="legacy/images/maps/maldives-location-map.webp" alt="Standortkarte der Malediven" loading="lazy" /></figure><p>Die Malediven liegen etwa 7 Grad nördlich des Äquators, was ihnen ein ganzjährig warmes, tropisches Klima beschert. Die geografischen Koordinaten der Malediven liegen bei ungefähr 3°15'' nördlicher Breite und 73°00'' östlicher Länge. Diese Lage platziert die Malediven mitten im Indischen Ozean, fernab jeder größeren Landmasse, was zu ihrer abgeschiedenen und friedlichen Atmosphäre beiträgt.</p><h2>Nähe zu den Nachbarländern</h2><figure><img src="legacy/images/maps/location-of-maldives.webp" alt="Lage der Malediven" loading="lazy" /></figure><p>Die Malediven liegen etwa 700 Kilometer südwestlich von Sri Lanka und 400 Kilometer südwestlich von Indien. Diese Nähe zu Südasien macht die Malediven von großen Städten der Region wie Colombo, Mumbai und Bangalore aus bequem mit dem Flugzeug erreichbar. Die Hauptstadt <a href="/maldives/islands/male/">Malé</a>, die auf einer der Inseln liegt, dient als wichtigstes Tor zu den Malediven und verfügt über einen internationalen Flughafen, der das Land mit der ganzen Welt verbindet.</p><h2>Die Atolle der Malediven</h2><figure><img src="legacy/images/maps/maldives-atoll-map.webp" alt="Atollkarte der Malediven" loading="lazy" /></figure><p>Die Malediven bestehen aus 26 natürlichen Atollen, die sich über eine Fläche von etwa 90.000 Quadratkilometern erstrecken. Diese Atolle sind in 20 Verwaltungsregionen unterteilt, die jeweils aus zahlreichen kleinen Inseln bestehen. Das Besondere an den Malediven ist, dass ihre Landfläche verhältnismäßig klein ist, sie sich aber über ein riesiges Meeresgebiet erstrecken. Das größte Atoll der Malediven ist das Baa-Atoll, das zugleich ein UNESCO-Biosphärenreservat ist und für seine reiche Artenvielfalt und seine unberührte Meeresumwelt bekannt ist.</p><h2>Bedeutung der Lage der Malediven</h2><figure><img src="legacy/images/maps/indian-ocean.webp" alt="Bedeutung der Lage der Malediven" loading="lazy" /></figure><p>Die Lage der Malediven ist aus mehreren Gründen bedeutsam. Erstens sorgt die Nähe zum Äquator für ein ganzjährig warmes und sonniges Klima – ideal für Strandurlauber und Wassersportbegeisterte. Zweitens vermittelt die Abgeschiedenheit der Malediven inmitten des Indischen Ozeans ein Gefühl von Abgeschiedenheit und Exklusivität, das bei Touristen, die eine friedliche Auszeit suchen, hoch geschätzt wird. Und schließlich beherbergen die umliegenden Gewässer einige der schönsten Korallenriffe und Meereslebewesen der Welt, was die Malediven zu einem erstklassigen Ziel für Schnorcheln und Tauchen macht.</p><h2>Wie man zu den Malediven kommt</h2><p>Die Anreise zu den Malediven ist vergleichsweise einfach, mit Direktflügen von mehreren großen Städten weltweit. Die meisten Besucher kommen am Velana International Airport an, der auf der Insel Hulhulé nahe der Hauptstadt Malé liegt. Von dort aus erreichen Reisende ihre Resortinseln je nach Entfernung vom Flughafen per Speedboot, Wasserflugzeug oder Inlandsflug. Die abgelegene Lage der Malediven bedeutet, dass Sie nach Ihrer Ankunft von der Ruhe des Ozeans umgeben sind – begleitet nur vom Rauschen der Wellen.</p><h2>Fazit: Ein abgelegenes tropisches Paradies</h2><p>Die Lage der Malediven mitten im Indischen Ozean macht sie zu einem wirklich einzigartigen Reiseziel. Ihre geografische Lage, kombiniert mit ihrer natürlichen Schönheit und der ruhigen Umgebung, zieht Besucher aus aller Welt an. Ob romantische Flitterwochen, Familienurlaub oder ein abenteuerreicher Urlaub – die Malediven bieten vor der Kulisse eines der schönsten Orte der Erde für jeden etwas.</p>', 'Wo liegen die Malediven? | Malediven Reiseführer | MTG', 'Wo liegen die Malediven? Entdecken Sie, wo sich dieses tropische Paradies befindet und warum es für Reisende aus aller Welt zu den Top-Reisezielen zählt.', 'published', 'claude')
on conflict (entity_id, locale) do update set
  slug = excluded.slug, title = excluded.title, short_description = excluded.short_description,
  body_html = excluded.body_html, meta_title = excluded.meta_title, meta_description = excluded.meta_description,
  translation_status = excluded.translation_status, translated_by = excluded.translated_by, updated_at = now();
